components.css:
.ds-site-header{display:flex;align-items:center;justify-content:space-between;height:72px}
.ds-wordmark{font:400 1.375rem/1 var(--serif);text-decoration:none;letter-spacing:-.01em}
.ds-icon-link{display:grid;place-items:center;width:44px;height:44px;margin-right:-10px;border-radius:999px;transition:background-color .2s var(--ease)}
.ds-icon-link:hover{background:var(--blue-wash)}
.ds-site-header{color:var(--blue);font:400 1.125rem/1.55 var(--sans);}.ds-site-header a{color:inherit}.ds-site-header a:focus-visible{outline:2px solid var(--blue);outline-offset:3px;box-shadow:0 0 0 6px var(--amber);border-radius:4px}

.ds-annotate{position:relative;white-space:nowrap}
.ds-annotate-mark{position:absolute;left:-2%;bottom:-.14em;width:104%;height:.22em;overflow:visible;pointer-events:none}
.ds-annotate-mark path{fill:none;stroke:var(--pink);stroke-width:4;stroke-linecap:round;vector-effect:non-scaling-stroke}
.ds-annotate{white-space:normal}
.ds-annotate-mark{transform-origin:left center;animation:draw 1.1s .35s var(--ease) both}
.ds-annotate{color:var(--blue);font:400 clamp(2.5rem,5.2vw,4.5rem)/1.02 var(--serif);letter-spacing:-.025em}@media(max-width:639px){.ds-annotate{white-space:normal}}@media(prefers-reduced-motion:no-preference){.ds-annotate-mark{transform-origin:left center;animation:ds-draw 1.1s .35s var(--ease) both}@keyframes ds-draw{from{transform:scaleX(0)}}}
